"""Compile a fresh seven-class retention prefix; qualification is a separate step."""
import argparse
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import shutil

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
PACKAGE = Path('org/eclipse/rdf4j/sail/lmdb/evaluation')
NAMES = ('NativeResultMaterializer', 'NativeProjectedBindingSet', 'NativeDirectValueMemo',
         'NativeDirectValueMemo$WeakValueEntry', 'NativeDirectValueMemoStatistics',
         'NativeDirectValueMemoStatistics$Snapshot', 'DirectMemoLauncher')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted:
        raise ValueError('Exclusive Java slot required')
    red = json.loads((HERE / 'validation/red-all-v1/receipt.json').read_text())
    if not red['passed'] or red['results'] != dict(tests=8, failures=5, errors=0, skipped=0):
        raise ValueError('The accepted pre-implementation red evidence is required')
    spec = importlib.util.spec_from_file_location('retention_contract_runner', HERE / 'run_contracts.py')
    helper = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(helper)
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    shutil.copyfile(__file__, output / 'compiler-at-launch.py')
    baseline = PHASE / 'recovery/runtime-v1'
    cp_file = baseline / 'baseline/classpath.txt'
    cp = cp_file.read_text().strip()
    sources = sorted((PHASE / 'implementation-src').rglob('*.java'))
    sources += sorted((PHASE / 'benchmark/src').rglob('*.java'))
    if len(sources) != 5:
        raise ValueError('Expected exactly five explicit feature sources')
    copied, identities = [], {}
    for source in sources:
        destination = output / 'src' / PACKAGE / source.name
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)
        copied.append(destination)
        identities[str(source)] = helper.digest(source)
    helper.write(output / 'sources.json', identities)
    emitted, prefix = output / 'emitted-classes', output / 'classes'
    emitted.mkdir()
    prefix.mkdir()
    result = helper.run(output, 'compile', [helper.JAVA_HOME / 'bin/javac', '--release', '25', '-g',
        '-proc:none', '-implicit:none', '-sourcepath', '', '-encoding', 'UTF-8', '-cp', cp,
        '-d', emitted, *copied])
    if result['exitCode']:
        print((output / 'compile.log').read_text())
        raise RuntimeError('Retention prefix did not compile')
    expected = {str(PACKAGE / (name + '.class')) for name in NAMES}
    retained = set(json.loads((baseline / 'direct/retained-baseline-class-files.json').read_text()))
    if set(helper.tree(emitted)) != expected | retained:
        raise ValueError('Unexpected compiled class set')
    for name in sorted(expected):
        destination = prefix / name
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(emitted / name, destination)
    old = baseline / 'direct/src' / PACKAGE
    for name in ('NativeResultMaterializer.java', 'NativeProjectedBindingSet.java'):
        if helper.digest(old / name) != helper.digest(output / 'src' / PACKAGE / name):
            raise ValueError('Ownership integration source changed')
    plan = str(PACKAGE / 'NativeResultMaterializerPlan.class')
    if helper.digest(emitted / plan) != helper.digest(baseline / 'baseline/artifacts/001-classes' / plan):
        raise ValueError('Retained plan binary changed')
    helper.write(output / 'class-files.json', helper.tree(prefix))
    (output / 'classpath.txt').write_text(str(prefix) + os.pathsep + cp + '\n')
    helper.write(output / 'compile-receipt.json', {
        'compiled': True, 'qualifiedForTiming': False, 'retainedBaselineNestedClasses': sorted(retained),
        'selectedClasses': sorted(expected), 'ownershipIntegrationSourcesIdentical': True,
        'sourceHashes': identities, 'classpathFile': str(output / 'classpath.txt'),
        'classpathSha256': helper.digest(output / 'classpath.txt'),
        'classFilesSha256': helper.digest(output / 'class-files.json')})
    print(json.dumps({'output': str(output), 'prefixClasses': len(expected), 'qualifiedForTiming': False}))


if __name__ == '__main__':
    main()
